import{_ as a,o as t,c as o,a5 as i}from"./chunks/framework.BwlBv862.js";const p=JSON.parse('{"title":"Requirements","description":"","frontmatter":{"title":"Requirements","docId":"user.start.requirements","translationKey":"user.start.requirements","locale":"en","audience":"user","featureStatus":"available","contentStatus":"reviewed","sourceLocale":"en","sourceRevision":"c68c149552a943cf0f03393c5dac91bd62abf9c50f791d7b0757599754f4804e","translationRevision":"c68c149552a943cf0f03393c5dac91bd62abf9c50f791d7b0757599754f4804e","order":10},"headers":[],"relativePath":"en/user/requirements.md","filePath":"en/user/requirements.md","lastUpdated":1794611623000}'),r={name:"en/user/requirements.md"};function n(s,e,l,d,c,u){return t(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="requirements" tabindex="-1">Requirements <a class="header-anchor" href="#requirements" aria-label="Permalink to &quot;Requirements {#requirements}&quot;">​</a></h1><h2 id="goal" tabindex="-1">Goal <a class="header-anchor" href="#goal" aria-label="Permalink to &quot;Goal {#goal}&quot;">​</a></h2><p>Choose a supported desktop package and identify the services needed for your intended workflow before installing.</p><h2 id="what-you-need" tabindex="-1">What you need <a class="header-anchor" href="#what-you-need" aria-label="Permalink to &quot;What you need {#what-you-need}&quot;">​</a></h2><ul><li>A Windows x86_64 or Linux x86_64 computer for the published desktop packages. The current release workflow builds these two targets. It does not publish a macOS desktop or Android APK.</li><li>A working graphical session. Windows needs Microsoft&#39;s WebView2 Runtime. Linux needs a compatible GTK/WebKitGTK environment; the DEB declares its runtime packages and the AppImage carries reviewed media helpers.</li><li>Network access to TikTok for an actual LIVE connection. An offline room, expired guest session or upstream rate limit cannot be corrected by changing an automation.</li><li>Storage outside the installation directory for SQLite data, plugins and logs. The app resolves a per-user data directory; moving the executable does not move that data.</li></ul><p>A Cloud account is needed for account-based catalog or collaboration operations, not for every local editor. OBS is needed only if you want to display a widget in a broadcast. Audio/TTS integrations may require a separately installed plugin and its own provider or service.</p><h2 id="check-the-environment" tabindex="-1">Check the environment <a class="header-anchor" href="#check-the-environment" aria-label="Permalink to &quot;Check the environment {#check-the-environment}&quot;">​</a></h2><ol><li>Select the package matching your operating system and x86_64 architecture.</li><li>On Windows, install WebView2 if the installer reports it missing. On Linux, resolve missing runtime libraries through your distribution package manager.</li><li>Confirm the app can open its window before connecting to TikTok or adding plugins.</li><li>Continue with <a href="./installation.html">installation</a> and then <a href="./first-live.html">your first LIVE</a>.</li></ol><h2 id="expected-result" tabindex="-1">Expected result <a class="header-anchor" href="#expected-result" aria-label="Permalink to &quot;Expected result {#expected-result}&quot;">​</a></h2><p>The application opens and its main navigation is usable while offline. Optional integrations may remain unavailable until their plugin or host capability is present.</p><h2 id="recovery" tabindex="-1">Recovery <a class="header-anchor" href="#recovery" aria-label="Permalink to &quot;Recovery {#recovery}&quot;">​</a></h2><p>For a blank window or an early exit, collect startup diagnostics and the exact package version. The AppImage and DEB are different installation formats; neither is an Android executable. See <a href="./termux.html">Termux and headless scope</a> for that environment. Building from source has additional requirements in the developer guide.</p><h2 id="operational-details" tabindex="-1">Operational details <a class="header-anchor" href="#operational-details" aria-label="Permalink to &quot;Operational details {#operational-details}&quot;">​</a></h2><p>If the window never opens, use native <code>tiktools.log</code> (<code>controller.log</code> for controller mode): Windows <code>%LOCALAPPDATA%/TikTools/logs</code>, Linux <code>${XDG_DATA_HOME:-~/.local/share}/TikTools/logs</code>, unless <code>TIKTOOLS_HOME</code> or <code>TIKTOOLS_LOG_DIR</code> changes the location. Logging initialization can fail before a file exists. Retain any terminal error and follow <a href="./preferences/troubleshooting.html#operational-details">diagnostic retention and privacy</a> before sharing.</p>',14)])])}const m=a(r,[["render",n]]);export{p as __pageData,m as default};
